async function worldInstancePost(route,body,context={}){
      const controller=new AbortController(),external=context?.signal,cancel=()=>controller.abort();
      const timeout=setTimeout(cancel,12000);
      if(external?.aborted)cancel();else external?.addEventListener('abort',cancel,{once:true});
      try{return await postJson(route,body,{retries:0,signal:controller.signal});}
      catch(error){if(controller.signal.aborted)throw Error(external?.aborted?'request_cancelled':'request_timeout');throw error;}
      finally{clearTimeout(timeout);external?.removeEventListener('abort',cancel);}
    }

async function worldTrialRequest(action,extra={}){
      const preview=state.preview,route=preview?new URL("/api/preview/dwelling/trial",location.origin).toString():"/api/miniapp/xianxia-dwelling/trial";
      const body={action,...extra,...(preview?{previewId:townPreviewIdentity()}:{token:state.token,initData:state.initData})};
      const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);
      try{
        const data=await postJson(route,body,{retries:0,signal:controller.signal});
        if(!data?.ok||!data.trial)return null;
        if((data.trial.grants||[]).length||data.trial.cultivation)state.sectionLoaded.inventory=false;
        return data.trial;
      }catch(error){console.warn("[trial]",action,error);return null;}finally{clearTimeout(timeout);}
    }

