window.qingxiInstanceRequest=async function(resource,action,extra={},context={}){
      const keys={'mulan-shrine':'mulanShrine','baiqiao-puppet':'baiqiaoPuppet','jianzhong-trial':'jianzhongTrial'},key=keys[resource];
      if(!key||!worldStoryContentAvailable())return {ok:false,error:'instance_not_open'};
      try{
        const route=state.preview?`/api/preview/dwelling/${resource}`:`/api/miniapp/xianxia-dwelling/${resource}`;
        const data=await worldInstancePost(route,{...extra,action,...(state.preview?{previewId:questPreviewIdentity()}:{token:state.token,initData:state.initData})},context);
        if(data?.[key]?.grants?.length||data?.[key]?.cultivation)state.sectionLoaded.inventory=false;
        if(data?.[key]?.questStep)void worldQuests?.refresh?.(false);
        return data;
      }catch(error){return {ok:false,error:error.message||'instance_unavailable'};}
    }
